<?php
namespace OpenLMS\Controllers;

use OpenLMS\Policies\CoursePolicy;
use PDO;

trait LearningHelpersTrait
{
    private static function subjectRowsForUser(PDO $pdo,array $user): array
    {
        if(in_array('student',$user['roles'],true)){
            $sql="SELECT s.* FROM subjects s WHERE s.status='active' AND EXISTS (SELECT 1 FROM courses c WHERE c.subject_id=s.id AND c.status='published' AND (EXISTS (SELECT 1 FROM enrollments e WHERE e.course_id=c.id AND e.user_id=? AND e.status IN ('active','completed')) OR EXISTS (SELECT 1 FROM course_batches cb INNER JOIN batch_members bm ON bm.batch_id=cb.batch_id WHERE cb.course_id=c.id AND bm.user_id=?))) ORDER BY s.name";$st=$pdo->prepare($sql);$st->execute([(int)$user['id'],(int)$user['id']]);return $st->fetchAll();
        }
        if(in_array('teacher',$user['roles'],true) && !self::canManageSubjects($user)) return $pdo->query("SELECT * FROM subjects WHERE status='active' ORDER BY name")->fetchAll();
        return $pdo->query('SELECT * FROM subjects ORDER BY status, name')->fetchAll();
    }

    private static function subjectStats(PDO $pdo,int $subjectId,array $user): array
    {
        $courses=self::courseRowsForSubject($pdo,$subjectId,$user);$totalCourses=count($courses);$totalLessons=0;$teacherName=null;$progressValues=[];
        foreach($courses as $c){$totalLessons+=self::courseLessonCount($pdo,(int)$c['id'],$user);$teacherName??=$c['teacher_name']??null;if(in_array('student',$user['roles'],true))$progressValues[]=self::courseProgress($pdo,(int)$c['id'],(int)$user['id'],$user);}
        return ['total_courses'=>$totalCourses,'total_lessons'=>$totalLessons,'teacher_name'=>$teacherName,'progress_percent'=>$progressValues?(int)round(array_sum($progressValues)/count($progressValues)):0];
    }

    private static function courseRowsForSubject(PDO $pdo,int $subjectId,array $user): array
    {
        $base='SELECT c.*,u.name teacher_name FROM courses c LEFT JOIN users u ON u.id=c.teacher_id WHERE c.subject_id=?';$args=[$subjectId];
        if(in_array('student',$user['roles'],true)){$base.=" AND c.status='published' AND (EXISTS (SELECT 1 FROM enrollments e WHERE e.course_id=c.id AND e.user_id=? AND e.status IN ('active','completed')) OR EXISTS (SELECT 1 FROM course_batches cb INNER JOIN batch_members bm ON bm.batch_id=cb.batch_id WHERE cb.course_id=c.id AND bm.user_id=?))";$args[]=(int)$user['id'];$args[]=(int)$user['id'];}
        elseif(in_array('teacher',$user['roles'],true)&&!self::canManageSubjects($user)){$base.=' AND c.teacher_id=? AND c.status<>\'archived\'';$args[]=(int)$user['id'];}
        else{$base.=" AND c.status<>'archived'";}
        $base.=' ORDER BY c.id DESC';$st=$pdo->prepare($base);$st->execute($args);return $st->fetchAll();
    }

    private static function loadCourse(PDO $pdo,int $id): ?array{$st=$pdo->prepare('SELECT c.*,s.name subject_name,s.code subject_code,s.status subject_status,u.name teacher_name,u.email teacher_email FROM courses c INNER JOIN subjects s ON s.id=c.subject_id LEFT JOIN users u ON u.id=c.teacher_id WHERE c.id=? LIMIT 1');$st->execute([$id]);$r=$st->fetch();return $r?:null;}
    private static function loadLesson(PDO $pdo,int $id): ?array{$st=$pdo->prepare('SELECT l.*,cs.course_id,cs.title section_title,cs.sort_order section_order FROM lessons l INNER JOIN course_sections cs ON cs.id=l.course_section_id WHERE l.id=? LIMIT 1');$st->execute([$id]);$r=$st->fetch();return $r?:null;}
    private static function materialForLesson(PDO $pdo,int $id,int $lessonId): ?array{$st=$pdo->prepare('SELECT * FROM learning_materials WHERE id=? AND lesson_id=? LIMIT 1');$st->execute([$id,$lessonId]);$r=$st->fetch();return $r?:null;}
    private static function materials(PDO $pdo,int $lessonId):array{$st=$pdo->prepare('SELECT * FROM learning_materials WHERE lesson_id=? ORDER BY id DESC');$st->execute([$lessonId]);return $st->fetchAll();}
    private static function links(PDO $pdo,int $lessonId):array{$st=$pdo->prepare('SELECT * FROM lesson_links WHERE lesson_id=? ORDER BY id');$st->execute([$lessonId]);return $st->fetchAll();}
    private static function prerequisiteIds(PDO $pdo,int $lessonId):array{$st=$pdo->prepare('SELECT prerequisite_lesson_id FROM lesson_prerequisites WHERE lesson_id=?');$st->execute([$lessonId]);return array_map('intval',$st->fetchAll(PDO::FETCH_COLUMN));}

    private static function canManageSubjects(array $user):bool{return (bool)array_intersect(['super_admin','administrator','hod'],$user['roles']??[]);}
    private static function canViewSubject(PDO $pdo,array $subject,array $user):bool{if(self::canManageSubjects($user))return true;if(in_array('teacher',$user['roles'],true))return $subject['status']==='active';$rows=self::courseRowsForSubject($pdo,(int)$subject['id'],$user);return !empty($rows);}
    private static function teacherAccounts(PDO $pdo):array{return $pdo->query("SELECT DISTINCT u.id,u.name,u.email FROM users u INNER JOIN user_roles ur ON ur.user_id=u.id INNER JOIN roles r ON r.id=ur.role_id WHERE r.name IN ('teacher','hod') AND u.status='active' ORDER BY u.name")->fetchAll();}
    private static function isStudent(PDO $pdo,int $id):bool{$st=$pdo->prepare("SELECT COUNT(*) FROM users u INNER JOIN user_roles ur ON ur.user_id=u.id INNER JOIN roles r ON r.id=ur.role_id WHERE u.id=? AND u.status='active' AND r.name='student'");$st->execute([$id]);return (int)$st->fetchColumn()>0;}

    private static function courseLessonCount(PDO $pdo,int $courseId,array $user):int{$sql='SELECT COUNT(*) FROM lessons l INNER JOIN course_sections cs ON cs.id=l.course_section_id WHERE cs.course_id=?';$args=[$courseId];if(in_array('student',$user['roles'],true)){$sql.=" AND l.status='published' AND (l.release_at IS NULL OR l.release_at<=?)";$args[]=gmdate('Y-m-d H:i:s');}$st=$pdo->prepare($sql);$st->execute($args);return (int)$st->fetchColumn();}
    private static function courseProgress(PDO $pdo,int $courseId,int $userId,array $user):int{if(!in_array('student',$user['roles'],true))return 0;$st=$pdo->prepare("SELECT COUNT(*) FROM lessons l INNER JOIN course_sections cs ON cs.id=l.course_section_id WHERE cs.course_id=? AND l.status='published' AND (l.release_at IS NULL OR l.release_at<=?)");$st->execute([$courseId,gmdate('Y-m-d H:i:s')]);$total=(int)$st->fetchColumn();if($total===0)return 0;$st=$pdo->prepare("SELECT COUNT(*) FROM lesson_progress lp INNER JOIN lessons l ON l.id=lp.lesson_id INNER JOIN course_sections cs ON cs.id=l.course_section_id WHERE cs.course_id=? AND lp.user_id=? AND lp.progress_percent=100 AND l.status='published' AND (l.release_at IS NULL OR l.release_at<=?)");$st->execute([$courseId,$userId,gmdate('Y-m-d H:i:s')]);return (int)round(((int)$st->fetchColumn()/$total)*100);}

    private static function courseSections(PDO $pdo,int $courseId,array $user,bool $canManage):array{$st=$pdo->prepare('SELECT * FROM course_sections WHERE course_id=? ORDER BY sort_order,id');$st->execute([$courseId]);$sections=$st->fetchAll();foreach($sections as &$s){$sql='SELECT l.*';$args=[];if(!$canManage)$sql.=',COALESCE(lp.progress_percent,0) progress_percent';$sql.=' FROM lessons l';if(!$canManage){$sql.=' LEFT JOIN lesson_progress lp ON lp.lesson_id=l.id AND lp.user_id=?';$args[]=(int)$user['id'];}$sql.=' WHERE l.course_section_id=?';$args[]=(int)$s['id'];if(!$canManage){$sql.=" AND l.status='published' AND (l.release_at IS NULL OR l.release_at<=?)";$args[]=gmdate('Y-m-d H:i:s');}$sql.=' ORDER BY l.sort_order,l.id';$q=$pdo->prepare($sql);$q->execute($args);$lessons=$q->fetchAll();if(!$canManage){$lessons=array_values(array_filter($lessons,fn($l)=>CoursePolicy::lessonAvailableForStudent($l,(int)$user['id'])));} $s['lessons']=$lessons;}unset($s);return $sections;}
    private static function allLessonsForCourse(PDO $pdo,int $courseId):array{$st=$pdo->prepare('SELECT l.*,cs.title section_title,cs.sort_order section_order FROM lessons l INNER JOIN course_sections cs ON cs.id=l.course_section_id WHERE cs.course_id=? ORDER BY cs.sort_order,cs.id,l.sort_order,l.id');$st->execute([$courseId]);return $st->fetchAll();}
    private static function neighborLessons(PDO $pdo,array $lessons,int $currentId,array $user,bool $canManage):array{$visible=[];foreach($lessons as $l){if($canManage||CoursePolicy::lessonAvailableForStudent($l,(int)$user['id']))$visible[]=$l;}$idx=null;foreach($visible as $i=>$l){if((int)$l['id']===$currentId){$idx=$i;break;}}return $idx===null?[null,null]:[$visible[$idx-1]??null,$visible[$idx+1]??null];}
    private static function lessonProgress(PDO $pdo,int $userId,int $lessonId):int{$st=$pdo->prepare('SELECT progress_percent FROM lesson_progress WHERE user_id=? AND lesson_id=?');$st->execute([$userId,$lessonId]);return (int)($st->fetchColumn()?:0);}
    private static function saveProgress(PDO $pdo,int $userId,int $lessonId,int $percent):void{$st=$pdo->prepare('SELECT COUNT(*) FROM lesson_progress WHERE user_id=? AND lesson_id=?');$st->execute([$userId,$lessonId]);$completed=$percent===100?gmdate('Y-m-d H:i:s'):null;if((int)$st->fetchColumn()>0)$pdo->prepare('UPDATE lesson_progress SET progress_percent=?,completed_at=? WHERE user_id=? AND lesson_id=?')->execute([$percent,$completed,$userId,$lessonId]);else$pdo->prepare('INSERT INTO lesson_progress (user_id,lesson_id,completed_at,progress_percent) VALUES (?,?,?,?)')->execute([$userId,$lessonId,$completed,$percent]);}

    private static function savePrerequisites(PDO $pdo,array $lesson,array $course,array $ids):void{$allowed=array_column(self::allLessonsForCourse($pdo,(int)$course['id']),'id');$allowed=array_map('intval',$allowed);$ids=array_values(array_unique(array_intersect($ids,$allowed)));$ids=array_values(array_filter($ids,fn($v)=>(int)$v!==(int)$lesson['id']));if(self::prerequisiteCycleWouldExist($pdo,(int)$lesson['id'],$ids,(int)$course['id']))throw new \RuntimeException('That prerequisite selection would create a lesson dependency cycle.');$pdo->beginTransaction();try{$pdo->prepare('DELETE FROM lesson_prerequisites WHERE lesson_id=?')->execute([(int)$lesson['id']]);foreach($ids as $required)$pdo->prepare('INSERT INTO lesson_prerequisites (lesson_id,prerequisite_lesson_id) VALUES (?,?)')->execute([(int)$lesson['id'],$required]);$pdo->commit();}catch(\Throwable $e){if($pdo->inTransaction())$pdo->rollBack();throw $e;}}
    private static function prerequisiteCycleWouldExist(PDO $pdo,int $lessonId,array $proposed,int $courseId):bool{$lessons=self::allLessonsForCourse($pdo,$courseId);$allowed=array_fill_keys(array_map(fn($r)=>(int)$r['id'],$lessons),true);$graph=[];$st=$pdo->prepare('SELECT lesson_id,prerequisite_lesson_id FROM lesson_prerequisites');$st->execute();foreach($st->fetchAll() as $row){$from=(int)$row['lesson_id'];$to=(int)$row['prerequisite_lesson_id'];if(isset($allowed[$from])&&isset($allowed[$to])&&$from!==$lessonId)$graph[$from][]=$to;}$graph[$lessonId]=array_map('intval',$proposed);$visiting=[];$visited=[];$visit=function(int $node) use (&$visit,&$graph,&$visiting,&$visited):bool{if(isset($visiting[$node]))return true;if(isset($visited[$node]))return false;$visiting[$node]=true;foreach($graph[$node]??[] as $next){if($visit((int)$next))return true;}unset($visiting[$node]);$visited[$node]=true;return false;};foreach(array_keys($allowed) as $node){if($visit((int)$node))return true;}return false;}
    private static function moveLesson(PDO $pdo,int $lessonId,string $direction,int $courseId):void{$lesson=self::loadLesson($pdo,$lessonId);if(!$lesson||(int)$lesson['course_id']!==$courseId)return;$op=$direction==='up'?'<':'>';$sort=$direction==='up'?'DESC':'ASC';$st=$pdo->prepare("SELECT id,sort_order FROM lessons WHERE course_section_id=? AND sort_order $op ? ORDER BY sort_order $sort,id $sort LIMIT 1");$st->execute([(int)$lesson['course_section_id'],(int)$lesson['sort_order']]);$other=$st->fetch();if(!$other)return;$pdo->beginTransaction();try{$pdo->prepare('UPDATE lessons SET sort_order=? WHERE id=?')->execute([(int)$other['sort_order'],$lessonId]);$pdo->prepare('UPDATE lessons SET sort_order=? WHERE id=?')->execute([(int)$lesson['sort_order'],(int)$other['id']]);$pdo->commit();}catch(\Throwable $e){if($pdo->inTransaction())$pdo->rollBack();throw $e;}}
    private static function sectionBelongsToCourse(PDO $pdo,int $sectionId,int $courseId):bool{$st=$pdo->prepare('SELECT COUNT(*) FROM course_sections WHERE id=? AND course_id=?');$st->execute([$sectionId,$courseId]);return (int)$st->fetchColumn()>0;}
    private static function upsertEnrollment(PDO $pdo,int $userId,int $courseId,?int $batchId):void{$st=$pdo->prepare('SELECT id FROM enrollments WHERE user_id=? AND course_id=?');$st->execute([$userId,$courseId]);$id=(int)($st->fetchColumn()?:0);if($id)$pdo->prepare("UPDATE enrollments SET batch_id=?,status='active' WHERE id=?")->execute([$batchId,$id]);else$pdo->prepare("INSERT INTO enrollments (user_id,course_id,batch_id,enrolled_at,status) VALUES (?,?,?,?,'active')")->execute([$userId,$courseId,$batchId,gmdate('Y-m-d H:i:s')]);}
    private static function insertIgnore(PDO $pdo,string $table,array $data,array $unique):void{$where=[];$args=[];foreach($unique as $k){$where[]="$k=?";$args[]=$data[$k];}$st=$pdo->prepare('SELECT COUNT(*) FROM '.$table.' WHERE '.implode(' AND ',$where));$st->execute($args);if((int)$st->fetchColumn()>0)return;$cols=array_keys($data);$pdo->prepare('INSERT INTO '.$table.' ('.implode(',',$cols).') VALUES ('.implode(',',array_fill(0,count($cols),'?')).')')->execute(array_values($data));}

    private static function positiveIntOrNull(mixed $v):?int{$i=(int)$v;return $i>0?$i:null;}
    private static function idOrNull(mixed $v):?int{$i=(int)$v;return $i>0?$i:null;}
    private static function initials(string $name):string{$parts=preg_split('/\s+/',trim($name))?:[];$out='';foreach(array_slice($parts,0,2) as $p)$out.=mb_strtoupper(mb_substr($p,0,1));return $out?:'OL';}
    private static function humanBytes(int $bytes):string{return $bytes>=1048576?round($bytes/1048576,1).' MB':round($bytes/1024,1).' KB';}
    private static function friendlyDbError(\Throwable $e,string $fallback):string{$m=$e->getMessage();if(str_contains($m,'UNIQUE')||str_contains($m,'Duplicate'))return 'A record with that unique value already exists.';if($e instanceof \RuntimeException && !str_contains($m,'SQLSTATE'))return $m;return $fallback;}
    private static function notFoundOrDenied():never{http_response_code(404);render_page('Not found','<div class="card empty-state"><h2>Not found</h2><p>The requested learning resource is unavailable or you do not have access.</p></div>');exit;}
}
